-- POST-CHECK [A]: ร.ร.ตกค้างใต้ zone เก่า (คาด = 1)
SELECT COUNT(*) AS orphan_after FROM master_school WHERE sao_code IN (184,185,186,187,188,189,190,191,192,193,194,195,196,197,198,199,200,201,202,203,204,205,206,207,208,209,210,211,212,213,214,215,216,217,218,219,220,221,222,223,224,225);
-- POST-CHECK [B]: ทุกบัญชี สพม. resolve ได้ (คาด resolvable = 62)
SELECT COUNT(*) AS resolvable FROM master_saonew sn JOIN master_sao ms ON TRIM(ms.sao_name)=TRIM(sn.code) WHERE sn.code LIKE 'สพม%';
-- POST-CHECK [C]: จำนวน ร.ร.ต่อเขตใหม่ (sao_id >= 233)
SELECT m.sao_code, TRIM(s.sao_name) sao_name, COUNT(*) schools FROM master_school m JOIN master_sao s ON s.sao_id=m.sao_code WHERE m.sao_code>=233 GROUP BY m.sao_code, s.sao_name ORDER BY m.sao_code;

